class Solution {
    public ListNode reverseKGroup(ListNode head, int k) {
        ListNode dummy = new ListNode(0, head);
        ListNode groupPrev = dummy;
        while (true) {
            ListNode kth = groupPrev;
            for (int i = 0; i < k; i++) {           // 往前数 k 个
                kth = kth.next;
                if (kth == null) {
                    return dummy.next;              // 不够 k 个，剩下的不动
                }
            }
            ListNode groupNext = kth.next;          // 下一组的开头
            ListNode prev = groupNext;              // prev 从 groupNext 开始
            ListNode cur = groupPrev.next;
            while (cur != groupNext) {              // 组内反转
                ListNode nxt = cur.next;            // 先记住下一个
                cur.next = prev;                    // 箭头掉头
                prev = cur;
                cur = nxt;
            }
            ListNode first = groupPrev.next;        // 这组原来的头，现在是尾
            groupPrev.next = kth;                   // 前面接上新的头
            groupPrev = first;
        }
    }
}

